solution.solution.cpp:
#include <string_view>

enum class Light { green, yellow, red };

Light next(Light now)
{
    switch (now)
    {
    case Light::green:  return Light::yellow;
    case Light::yellow: return Light::red;
    case Light::red:    return Light::green;
    }
    return Light::red;
}

int seconds(Light light)
{
    switch (light)
    {
    case Light::green:  return 30;
    case Light::yellow: return 5;
    case Light::red:    return 25;
    }
    return 0;
}

std::string_view action(Light light)
{
    switch (light)
    {
    case Light::green:  return "go";
    case Light::yellow: return "slow down";
    case Light::red:    return "stop";
    }
    return "stop";
}

int secondsFor(Light start, int changes)
{
    int total{ 0 };
    Light light{ start };
    for (int i{ 0 }; i < changes; ++i)
    {
        total += seconds(light);
        light = next(light);
    }
    return total;
}

unitTests:
TEST("next") { CHECK(next(Light::green) == Light::yellow); CHECK(next(Light::yellow) == Light::red); CHECK(next(Light::red) == Light::green); }
TEST("seconds") { CHECK_EQ(seconds(Light::green), 30); CHECK_EQ(seconds(Light::yellow), 5); CHECK_EQ(seconds(Light::red), 25); }
TEST("action") { CHECK_EQ(action(Light::green), "go"); CHECK_EQ(action(Light::yellow), "slow down"); CHECK_EQ(action(Light::red), "stop"); }
TEST("secondsFor") { CHECK_EQ(secondsFor(Light::green, 3), 60); CHECK_EQ(secondsFor(Light::red, 1), 25); CHECK_EQ(secondsFor(Light::yellow, 4), 65); CHECK_EQ(secondsFor(Light::green, 0), 0); }

